import { fileURLToPath } from 'node:url'
import react from '@vitejs/plugin-react'
import { defineConfig } from 'vite'

// Base stylesheet downloaded with tools/vendor-base-styles.sh.
const baseStyles = fileURLToPath(new URL('../../vendor/base-styles/packages/styles', import.meta.url))
const baseButtons = fileURLToPath(new URL('../../vendor/base-styles/packages/atoms', import.meta.url))
// NightMail's own icon set, generated by design/icons/tools/build.py (same path in tsconfig.app.json).
const nightmailIcons = fileURLToPath(new URL('../../design/icons/icons.ts', import.meta.url))

// The base stylesheet declares its own fonts (Inter, OpenDyslexic, Atkinson Hyperlegible) in base/_fonts.scss,
// which cannot be excluded from outside. NightMail uses the brand's own (styles/brand.css), so every @font-face
// coming from base.scss is dropped: without them Vite does not copy ~3.4 MB of fonts to dist and their licences
// need not be distributed.
const dropBaseFonts = {
  postcssPlugin: 'nightmail-drop-base-fonts',
  Once(root: { source?: { input?: { file?: string } }; walkAtRules: (name: string, cb: (rule: { remove: () => void }) => void) => void }) {
    if (!root.source?.input?.file?.endsWith('/src/styles/base.scss')) return
    root.walkAtRules('font-face', (rule) => rule.remove())
  },
}

// https://vite.dev/config/
export default defineConfig({
  plugins: [react()],
  resolve: {
    // Package names used inside the base stylesheet, resolved to vendor/base-styles.
    alias: [
      { find: /^~?@proton\/styles/, replacement: baseStyles },
      // Only its button SCSS is used (styles/base.scss), not its components.
      { find: /^@proton\/atoms/, replacement: baseButtons },
      { find: /^@nightmail\/icons$/, replacement: nightmailIcons },
    ],
  },
  css: {
    postcss: { plugins: [dropBaseFonts] },
    preprocessorOptions: {
      scss: {
        loadPaths: [`${baseStyles}/scss`],
        quietDeps: true,
        silenceDeprecations: ['import'],
      },
    },
  },
  // Tauri: fixed port and do not clear the console (see devUrl in tauri.conf.json).
  server: { port: 5173, strictPort: true },
  clearScreen: false,
})
